def main():
 out=ROOT/'validation/integrated/primaryP1_cycle6_closeout';out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py');assert not(ROOT/'runtime/STOP').exists();cycle=ROOT/'validation/integrated/primary_cycle6/summary.json';c=load(cycle);m=load(ROOT/'validation/integrated/primaryP1_full_mass2/summary.json');p=m['parts'];up=[r for r in p if r['part_ID'] not in ('GROUND_PLATE','TEST_BASE') and not r['part_ID'].startswith('FIXTURE_')];module=[r for r in p if r['part_ID']!='TEST_BASE' and not r['part_ID'].startswith('FIXTURE_')];gate=load(ROOT/'models/primary_system_gate_state7.json');pins={n:sha(REPO/n)==v for n,v in load(ROOT/'runtime/goal_authorized_20261127_7/ledger.json')['source_pins'].items()};assert all(pins.values());assert len(gate['gates'])==22 and all(g['status']=='UNQUALIFIED' for g in gate['gates']);assert len(up)==68 and len(module)==69
