 correction=dict(status='AUTHORITATIVE_SUBSET_LABEL_CORRECTION_NOT_MASS_CHANGE',scope='The original mass producer field module69_conditional_mass_kg excludedGround,so it enumerates68upstreamparts. Preserve that original field; this explicitcorrection supersedesitslabel in cycle6/mass summaries. Full78total and all numericalwrenches are unchanged.',upstream_excluding_ground_count=68,upstream_excluding_ground_mass_kg=sum(r['mass_kg'] for r in up),original_module_including_ground_count=69,original_module_including_ground_mass_kg=sum(r['mass_kg'] for r in module),total78_conditional_mass_kg=m['total_conditional_mass_kg'])
 r=dict(status='ACTUAL_P1_CYCLE6_EXACT_BYTE_HANDOFF_READY_NOT_RELEASE',producer=ref(out/'producer.py'),cycle=ref(cycle),candidate=c['candidate'],assembly=c['assembly'],actual_changed_CAD_files=c['actual_changed_CAD_files'],corrected_mass_scope=correction,report=ref(ROOT/'reports/primaryP1_fixture15_engineering.md'),checks=dict(all_source_pins_unchanged=all(pins.values()),all24execution_records_reaped=len(executions)==24,no_running_queue_tasks=True,one420secondtimeout_preserved=True,all22systemgatesunqualified=True,primary78parts=True,no_source_criteria_relaxation=True),source_pins_unchanged=pins,recorded_child_seconds=sum(e['elapsed_s'] for e in executions),recorded_children_reaped=len(executions),timeouts=1,owned_analysis_children_running=0,running_queue_tasks=0,newly_qualified_system_gate_ids=[],remaining_system_gate_ids=c['remaining_system_gate_ids'],next_task_id=c['next_task_id'],next_mechanism=c['next_mechanism'],whole_system_release=False,stage3_authorized=False,global_energy_qualified=False,hardware_status='HARDWARE_NOT_MEASURED',save_status='PENDING_SUPERVISOR_EXACT_SAVE',git_add_commit_attempted=False)
 dump(out/'summary.json',r)
 state=load(ROOT/'PRIMARY_PRODUCT.json');state.update(latest_closeout=ref(out/'summary.json'),mass_subset_correction=correction);dump(ROOT/'PRIMARY_PRODUCT.json',state)
 current=load(ROOT/'CURRENT_CANDIDATE.json');current.update(primary_state=ref(ROOT/'PRIMARY_PRODUCT.json'),latest_closeout=ref(out/'summary.json'),mass_subset_correction=correction);dump(ROOT/'CURRENT_CANDIDATE.json',current)
 for t in q['tasks']:
  if t['id'].startswith('goal_primary_'):t['primary_state']=ref(ROOT/'PRIMARY_PRODUCT.json')
 dump(ROOT/'INTEGRATED_TASKS.json',q);nt=load(ROOT/'NEXT_TASK.json');nt['next']=next(t for t in q['tasks'] if t['id']==c['next_task_id']);dump(ROOT/'NEXT_TASK.json',nt)
 print(json.dumps(dict(status=r['status'],children=len(executions),child_seconds=r['recorded_child_seconds'],correction=correction)))
